  function escapeHtml(str) {
    return String(str == null ? '' : str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function formatDuration(sec) {
    const s = Math.max(1, parseInt(sec, 10) || 1);
    const m = Math.floor(s / 60);
    const r = s % 60;
    return String(m).padStart(2, '0') + ':' + String(r).padStart(2, '0');
  }

  function getScriptAttrId() {
    try { return typeof getScriptId === 'function' ? getScriptId() : SCRIPT_TAG; }
    catch (_) { return SCRIPT_TAG; }
  }

  function toastInfo(msg) { try { if (typeof toastr !== 'undefined') toastr.info(msg); } catch (_) {} }
  function toastSuccess(msg) { try { if (typeof toastr !== 'undefined') toastr.success(msg); } catch (_) {} }
  function toastError(msg) { try { if (typeof toastr !== 'undefined') toastr.error(msg); } catch (_) {} }

  // 注入 no-referrer，确保网易云/QQ音乐封面图不被防盗链拦截
  try {
    const hdoc = HOST_WIN.document;
    if (hdoc && hdoc.head && !hdoc.querySelector('meta[name="referrer"]')) {
      const m = hdoc.createElement('meta');
      m.name = 'referrer';
      m.content = 'no-referrer';
      hdoc.head.appendChild(m);
    }
  } catch (_) {}

  // ==================== 音乐封面自动抓取与灵动岛联动播放 ====================
  const musicCoverCache = new Map();

  function normMusicUrl(u) {
    let s = String(u || '').trim();
    if (s.startsWith('//')) s = 'https:' + s;
    if (s.startsWith('http://')) s = 'https://' + s.slice(7);
    return /^https?:\/\//i.test(s) ? s : '';
  }

  async function fetchJsonTimed(url, ms = 4500) {
    return new Promise((resolve) => {
      const t = setTimeout(() => resolve(null), ms);
      HOST_WIN.fetch(url)
        .then(r => r.ok ? r.json() : null)
        .then(j => { clearTimeout(t); resolve(j); })
        .catch(() => { clearTimeout(t); resolve(null); });
    });
  }

  function normCoverToken(str) {
    return String(str || '').toLowerCase().replace(/[\s　·•・\-_'"`’‘“”.,，。!！?？:：;；/\&＋+]/g, '');
  }

  function stripCoverBrackets(str) {
    return String(str || '').replace(/[（(【\[《][^）)】\]》]*[）)】\]》]/g, '').trim();
  }

  function scoreCoverMatch(candTitle, candArtist, targetTitle, targetArtist) {
    const rawT = String(candTitle || '').trim();
    const rawA = String(candArtist || '').trim();
    const tgtT = String(targetTitle || '').trim();
    const tgtA = String(targetArtist || '').trim();
    const nCT = normCoverToken(rawT);
    const nCCT = normCoverToken(stripCoverBrackets(rawT));
    const nTT = normCoverToken(tgtT);
    const nTCT = normCoverToken(stripCoverBrackets(tgtT));
    const nCA = normCoverToken(rawA);
    const nTA = normCoverToken(tgtA);

    let score = 0;
    let titleOk = false;
    let artistOk = false;

    if (nTT) {
      if (nCT === nTT || (nTCT && nCCT === nTCT)) { score += 110; titleOk = true; }
      else if (nCT.includes(nTT) || (nTCT && nCT.includes(nTCT))) { score += 65; titleOk = true; }
      else if (nTT.includes(nCCT) && nCCT.length >= 2) { score += 35; titleOk = true; }
      else { score -= 60; }
    }

    const noiseRe = /(翻唱|原唱|cover|dj版|dj|remix|伴奏|纯音乐|消音|片段|加速|降调|吉他版|钢琴版|女生版|男生版|烟嗓|戏腔)/i;
    const candNoise = noiseRe.test(rawT);
    const tgtNoise = noiseRe.test(tgtT);
    if (candNoise && !tgtNoise) score -= 140;

    if (nTA) {
      const parts = tgtA.split(/[/,&、，\s]+/).map(x => normCoverToken(x)).filter(Boolean);
      const hit = (nCA && (nCA === nTA || nCA.includes(nTA) || nTA.includes(nCA))) || parts.some(pt => pt.length >= 2 && nCA.includes(pt));
      if (hit) { artistOk = true; score += (nCA === nTA ? 150 : 120); }
      else { artistOk = false; score -= 160; }
    } else {
      artistOk = !candNoise;
    }

    return { score, isCleanOriginal: titleOk && artistOk && !(candNoise && !tgtNoise) };
  }

  async function fetchMusicCoverCached(title, artist) {
    const key = `${(title || '').trim()}::${(artist || '').trim()}`;
    if (!title) return '';
    if (musicCoverCache.has(key)) return musicCoverCache.get(key);
    const kw = `${title || ''} ${artist || ''}`.trim();

    let bestCover = '';
    let bestScore = -9999;
    const consider = (url, ev) => {
      const u = normMusicUrl(url);
      if (!u) return false;
      if (ev.score > bestScore) {
        bestScore = ev.score;
        bestCover = u;
      }
      return ev.isCleanOriginal;
    };

    // 1. 优先匹配网易云原唱（按歌名 + 歌手校验，过滤翻唱）
    try {
      const j = await fetchJsonTimed(`https://my-lovat-beta.vercel.app/cloudsearch?keywords=${encodeURIComponent(kw)}&limit=8`, 4500);
      const songs = (j && j.result && Array.isArray(j.result.songs)) ? j.result.songs : [];
      let topNet = null;
      for (const s0 of songs) {
        const pic = s0 && s0.al && s0.al.picUrl;
        if (!pic) continue;
        const cArtist = (s0.ar || []).map(a => a && a.name).filter(Boolean).join(' / ');
        const ev = scoreCoverMatch(s0.name || '', cArtist, title, artist);
        if (!topNet || ev.score > topNet.ev.score) {
          topNet = { url: normMusicUrl(pic) + '?param=240y240', ev };
        }
      }
      if (topNet && consider(topNet.url, topNet.ev)) {
        musicCoverCache.set(key, bestCover);
        return bestCover;
      }
    } catch (_) {}

    // 2. 网易云无原唱时，优先降级到 QQ 音乐多接口匹配原唱（VKeys -> GD Studio -> 原 tang 接口）
    try {
      const j = await fetchJsonTimed(`https://api.vkeys.cn/v2/music/tencent?word=${encodeURIComponent(kw)}&num=8`, 4200);
      const arr = (j && Array.isArray(j.data)) ? j.data : [];
      let topVk = null;
      for (const x of arr) {
        const pic = normMusicUrl(x && (x.cover || x.pic) || '');
        if (!pic) continue;
        const ev = scoreCoverMatch(x.song || x.title || x.name || '', x.singer || x.artist || '', title, artist);
        if (!topVk || ev.score > topVk.ev.score) topVk = { url: pic, ev };
      }
      if (topVk && consider(topVk.url, topVk.ev)) {
        musicCoverCache.set(key, bestCover);
        return bestCover;
      }
    } catch (_) {}

    try {
      const arr = await fetchJsonTimed(`https://music-api.gdstudio.xyz/api.php?types=search&source=tencent&count=8&name=${encodeURIComponent(kw)}`, 4200);
      if (Array.isArray(arr) && arr.length) {
        let topGd = null;
        for (const x of arr) {
          if (!x || !x.pic_id) continue;
          const cArtist = Array.isArray(x.artist) ? x.artist.join(' / ') : String(x.artist || '');
          const ev = scoreCoverMatch(x.name || '', cArtist, title, artist);
          if (!topGd || ev.score > topGd.ev.score) topGd = { picId: x.pic_id, ev };
        }
        if (topGd) {
          const pj = await fetchJsonTimed(`https://music-api.gdstudio.xyz/api.php?types=pic&source=tencent&id=${encodeURIComponent(topGd.picId)}&size=300`, 3500);
          const pic = normMusicUrl((pj && pj.url) || `https://y.gtimg.cn/music/photo_new/T002R300x300M000${topGd.picId}.jpg`);
          if (consider(pic, topGd.ev)) {
            musicCoverCache.set(key, bestCover);
            return bestCover;
          }
        }
      }
    } catch (_) {}

    try {
      const j = await fetchJsonTimed(`https://tang.api.s01s.cn/music_open_api.php?msg=${encodeURIComponent(kw)}&type=json`, 3500);
      const arr = Array.isArray(j) ? j : (j && Array.isArray(j.data) ? j.data : []);
      let topTang = null;
      for (const x of arr.slice(0, 8)) {
        const pic = normMusicUrl(x && (x.album_pic || x.singer_pic || x.pic) || '');
        if (!pic) continue;
        const cArtist = Array.isArray(x.singer_name) ? x.singer_name.join(' / ') : String(x.singer_name || x.singer || x.artist || '');
        const ev = scoreCoverMatch(x.song_title || x.title || x.name || '', cArtist, title, artist);
        if (!topTang || ev.score > topTang.ev.score) topTang = { url: pic, ev };
      }
      if (topTang && consider(topTang.url, topTang.ev)) {
        musicCoverCache.set(key, bestCover);
        return bestCover;
      }
    } catch (_) {}

    // 3. iTunes 原唱封面兜底
    try {
      const j = await fetchJsonTimed(`https://itunes.apple.com/search?term=${encodeURIComponent(kw)}&media=music&limit=8`, 4200);
      const arr = (j && Array.isArray(j.results)) ? j.results : [];
      let topIt = null;
      for (const x of arr) {
        const art = x && x.artworkUrl100;
        if (!art) continue;
        const ev = scoreCoverMatch(x.trackName || '', x.artistName || '', title, artist);
        if (!topIt || ev.score > topIt.ev.score) {
          topIt = { url: normMusicUrl(art.replace('100x100bb', '300x300bb')), ev };
        }
      }
      if (topIt) consider(topIt.url, topIt.ev);
    } catch (_) {}

    musicCoverCache.set(key, bestCover);
    return bestCover;
  }

  function hydrateAllMusicCovers() {
    const pending = [];
    for (const chat of Object.values(runtime.chatsMap)) {
      for (const m of (chat.messages || [])) {
        if (m.type === 'music' && m.title && !m.cover) pending.push(m);
      }
    }
    if (!pending.length) return;
    const seenKeys = new Set();
    pending.forEach((m) => {
      const key = `${m.title}::${m.artist || ''}`;
      if (seenKeys.has(key)) return;
      seenKeys.add(key);
      fetchMusicCoverCached(m.title, m.artist).then((cover) => {
        if (!cover) return;
        let updated = false;
        for (const chat of Object.values(runtime.chatsMap)) {
          for (const msg of (chat.messages || [])) {
            if (msg.type === 'music' && msg.title === m.title && (msg.artist || '') === (m.artist || '') && !msg.cover) {
              msg.cover = cover;
              updated = true;
            }
          }
        }
        $('.lp-in-music').each(function () {
          const $card = $(this);
          if ($card.attr('data-mtitle') === m.title && ($card.attr('data-martist') || '') === (m.artist || '')) {
            $card.attr('data-mcover', cover);
            const $disc = $card.find('.lp-in-music-disc');
            if ($disc.length && !$disc.find('img').length) {
              $disc.prepend($('<img>').attr({ src: cover, referrerpolicy: 'no-referrer', alt: '' }));
            }
          }
        });
        if (updated) pushStateToIframe();
      });
    });
  }

